add_action( 'woocommerce_product_bulk_edit_start', 'perfectpixel_bulk_remove_categories_field' );
add_action( 'woocommerce_product_bulk_edit_save', 'perfectpixel_bulk_remove_categories_save' );

function perfectpixel_bulk_remove_categories_field() {
	$terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => false ) );
	if ( ! $terms || is_wp_error( $terms ) ) {
		return;
	}
	echo '<div class="inline-edit-group"><label class="alignleft" style="width:100%"><span class="title">Αφαίρεση κατηγοριών</span>';
	echo '<select name="perfectpixel_remove_cats[]" multiple size="5" style="width:100%;max-width:300px">';
	foreach ( $terms as $term ) {
		echo '<option value="' . esc_attr( $term->term_id ) . '">' . esc_html( $term->name ) . '</option>';
	}
	echo '</select></label></div>';
}

function perfectpixel_bulk_remove_categories_save( $product ) {
	if ( empty( $_REQUEST['perfectpixel_remove_cats'] ) || ! current_user_can( 'edit_product', $product->get_id() ) ) {
		return;
	}
	$remove = array_map( 'absint', (array) wp_unslash( $_REQUEST['perfectpixel_remove_cats'] ) );
	wp_remove_object_terms( $product->get_id(), $remove, 'product_cat' );
	wc_delete_product_transients( $product->get_id() );
}
